/// <summary>
/// Event handler for class SrsProxy
/// </summary>
class AVADAISrsProxy_cls_EventHandler
{
}

Method.Source:
/// <summary>
/// Post event handler for renderReportToByteArray
/// </summary>
/// <param name="args">XppPrePostArgs</param>
[PostHandlerFor(classStr(SrsProxy), methodStr(SrsProxy, renderReportToByteArray))]
public static void SrsProxy_Post_renderReportToByteArray(XppPrePostArgs args)
{
    SRSProxy    srsProxy = args.getThis();
    if(isConfigurationkeyEnabled(configurationKeyNum(AVADAI)))
    {
        if(    !args.existsArg(identifierStr(_parameterValueArray))
            || !args.existsArg(identifierStr(_deviceInfo))
            || !args.existsArg(identifierStr(_reportPath)))
        {
            throw error(strFmt("@AVADAI:AVADAIWrongParam", funcName()));
        }

        Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[]  parameterValueArray = args.getArg(identifierStr(_parameterValueArray));
        str                                                                                 deviceInfo          = args.getArg(identifierStr(_deviceInfo));
        str                                                                                 reportPath          = args.getArg(identifierStr(_reportPath));
        System.Byte[] archiveByte = args.getReturnValue();


        if (!srsProxy.AVADAIparmCalledArchive() && srsProxy.AVADAIisArchiveReport(reportPath) && srsProxy.AVADAIparmCalledRVRefreshComplete())
        {
           srsProxy.AVADAIprintToArchive(reportPath, parameterValueArray, SRSReportFileFormat::PDF, deviceInfo,archiveByte);
        }
    }
}

/// <summary>
/// Post event handler for renderReportToPrinter
/// </summary>
/// <param name="args">XppPrePostArgs</param>
[PostHandlerFor(classStr(SrsProxy), methodStr(SrsProxy, renderReportToPrinter))]
public static void SrsProxy_Post_renderReportToPrinter(XppPrePostArgs args)
{
    SrsProxy            srsProxy = args.getThis();

    if(isConfigurationkeyEnabled(configurationKeyNum(AVADAI)))
    {
        if(    !args.existsArg(identifierStr(parameterValueArray))
            || !args.existsArg(identifierStr(deviceInfo))
            || !args.existsArg(identifierStr(reportPath)))
        {
            throw error(strFmt("@AVADAI:AVADAIWrongParam", funcName()));
        }

        Microsoft.Dynamics.AX.Framework.Reporting.Shared.ReportingService.ParameterValue[]  parameterValueArray = args.getArg(identifierStr(parameterValueArray));
        str                                                                                 deviceInfo          = args.getArg(identifierStr(deviceInfo));
        str                                                                                 reportPath          = args.getArg(identifierStr(reportPath));

        if (!srsProxy.AVADAIparmCalledArchive() && srsProxy.AVADAIisArchiveReport(reportPath))
        {
            setPrefix("@AVADAI:AVADAIShort");

            srsProxy.AVADAIprintToArchive(reportPath, parameterValueArray, SRSReportFileFormat::PDF, deviceInfo,Null);
        }
    }
}
